{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.d2p_tool_transformed_dates AS WITH base_data AS ( SELECT *, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', CASE WHEN design_approval_sent = 1751179296000 THEN NULL ELSE TO_TIMESTAMP((design_approval_sent / 1000)::INTEGER) END ) AS design_approved_monica_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((created_at_1 / 1000)::INTEGER)) AS design_created_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((pd_acceptance_time / 1000)::INTEGER)) AS pd_acceptance_time_, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', COALESCE( TO_TIMESTAMP(TRY_TO_NUMBER(EXPECTED_DELIVERED_DATE) / 1000), TRY_TO_TIMESTAMP(EXPECTED_DELIVERED_DATE) ) ) AS expected_delivered_date_, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((design_approval_recieved / 1000)::INTEGER)) AS design_approved_Sid_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((last_updated_at / 1000)::INTEGER)) AS last_updated_at_ist, TRY_TO_TIMESTAMP(fabric_sample_sourcing, \'MON DD, YYYY HH12:MI AM\') AS fabric_sample_sourcing_design_time, TRY_TO_TIMESTAMP(fabric_sample_received_production, \'MON DD, YYYY HH12:MI AM\') AS proto_received_production_time, TRY_TO_TIMESTAMP(sample_given_back_to_design, \'MON DD, YYYY HH12:MI AM\') AS proto_given_back_to_design_time, TRY_TO_TIMESTAMP(fabric_reference_prod_time, \'MON DD, YYYY HH12:MI AM\') AS fabric_reference_production_time, sku_group AS sku, REGEXP_SUBSTR_ALL(C1, \'[A-Z][a-z]{2}\\s+\\d{1,2},\\s+\\d{4}\\s+\\d{1,2}:\\d{2}\\s+[AaPp][Mm]\') AS c1_dates_array, REGEXP_SUBSTR_ALL(C2, \'[A-Z][a-z]{2}\\s+\\d{1,2},\\s+\\d{4}\\s+\\d{1,2}:\\d{2}\\s+[AaPp][Mm]\') AS c2_dates_array FROM SNITCH_DB.MAPLEMONK.XANO_GET_DESIGN_PRODUCTION_INFO ), transformed_data_d2p AS ( SELECT *, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-1]), \'MON DD, YYYY HH12:MI AM\' ) AS original_date_proto_received_production_time, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-2]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_1_proto_received_production_time, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-3]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_2_fabric_sample_received_prod, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-1]), \'MON DD, YYYY HH12:MI AM\' ) AS original_date_proto_given_back_to_design_time, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-2]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_1_proto_given_back_to_design_time, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-3]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_2_proto_given_back_to_design_time FROM base_data ), data_with_latest_timestamp AS ( SELECT *, GREATEST( COALESCE(design_created_time, \'1970-01-01\'), COALESCE(design_approved_monica_time, \'1970-01-01\'), COALESCE(design_approved_Sid_time, \'1970-01-01\'), COALESCE(pd_acceptance_time_, \'1970-01-01\'), COALESCE(fabric_approval_sid_time, \'1970-01-01\'), COALESCE(fabric_sample_sourcing_design_time, \'1970-01-01\'), COALESCE(proto_received_production_time, \'1970-01-01\'), COALESCE(proto_given_back_to_design_time, \'1970-01-01\'), COALESCE(fabric_reference_production_time, \'1970-01-01\') ) AS last_update_timestamp FROM transformed_data_d2p ), data_with_initial_status AS ( SELECT *, CASE WHEN lower(comments) like \'%job work%\' or lower(PD_ACCEPTANCE_STATUS) LIKE \'%job work%\' THEN \'JobWork SKU\' WHEN original_date_proto_given_back_to_design_time IS NOT NULL AND proto_received_production_time IS NOT NULL and expected_delivered_date is not null THEN \'Inward Pending\' WHEN pd_acceptance_status = \'Hold\' THEN \'PD On Hold\' WHEN expected_delivered_date is not null THEN \'Inward Pending\' WHEN pd_acceptance_status = \'Rejected\' THEN \'PD Rejected\' WHEN design_approval_status = \'Sent to Sid\' AND fabric_sample_sourcing is null THEN \'Sid Approval Pending\' WHEN original_date_proto_given_back_to_design_time is not null AND expected_delivered_date is null THEN \'Final Proto Approval Pending\' WHEN design_approval_status = \'Sent to Monica\' THEN \'Monica Approval Pending\' WHEN techpack_link like \'%https%\' AND PD_ACCEPTANCE_STATUS = \'\' THEN \'PD Acceptance Pending\' WHEN proto_received_production_time IS NULL AND proto_received_production_time IS NOT NULL THEN \'Proto Submission back to design Pending\' ELSE CASE WHEN lower(tech_pack) NOT LIKE \'%https%\' THEN \'Tech Pack Link Pending\' WHEN fabric_sample_sourcing <> \'\' AND original_date_proto_received_production_time is null AND expected_delivered_date is null THEN \'Proto Sample Receiving Pending Production\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Accepted\' AND original_date_proto_received_production_time is null THEN \'Fabric Approval Pending\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Rejected\' THEN \'PD Rejected\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Hold\' THEN \'PD On Hold\' ELSE \'No Data\' END END AS initial_last_update_status FROM data_with_latest_timestamp ) SELECT *, CASE WHEN initial_last_update_status = \'No Data\' THEN CASE WHEN tech_pack = \'\' OR tech_pack LIKE \'Tec%\' THEN \'Tech Pack Link Pending\' WHEN tech_pack like \'%https%\' AND PD_ACCEPTANCE_STATUS = \'\' THEN \'PD Acceptance Pending\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Accepted\' THEN \'Fabric Approval Pending\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Rejected\' THEN \'PD Rejected\' WHEN design_approval_status = \'Approved by Sid\' AND pd_acceptance_status = \'Hold\' THEN \'PD On Hold\' ELSE \'Tech Pack Link Pending\' END ELSE initial_last_update_status END AS last_update_status FROM data_with_initial_status;",
                    "transaction": true
                }
            ) }}
